import java.sql.*;import java.nio.file.*;import java.util.*;import java.time.*;import com.fasterxml.jackson.databind.ObjectMapper;
/** Current source metadata only, no goals, tokens, source content or licensing mutation. */
public class InspectCurrentSourceAdmission {
 public static void main(String[]a)throws Exception {if(a.length!=1||Files.exists(Path.of(a[0])))throw new IllegalArgumentException("NEW_REPORT");var rows=new ArrayList<Map<String,Object>>();
 try(var c=DriverManager.getConnection("jdbc:dm://127.0.0.1:5301","CONPROD",System.getenv("PROTECTION_INSPECT_PASSWORD"))){c.setReadOnly(true);c.setAutoCommit(false);try(var s=c.prepareStatement("SELECT c.source_id,c.contract_version,c.decision_id,c.source_epoch,c.status,k.valid_until,a.valid_until,f.field_code,f.use_code,f.valid_until FROM CONPROD.con4_source_current c JOIN CONPROD.con4_source_contract k ON k.source_id=c.source_id AND k.contract_version=c.contract_version JOIN CONPROD.con4_source_admission a ON a.decision_id=c.decision_id JOIN CONPROD.con4_source_field_use f ON f.decision_id=a.decision_id ORDER BY c.source_id,f.field_code,f.use_code")){s.setQueryTimeout(15);try(var r=s.executeQuery()){while(r.next()){var row=new TreeMap<String,Object>();row.put("source",r.getString(1));row.put("contract",r.getString(2));row.put("decision",r.getString(3));row.put("epoch",r.getLong(4));row.put("status",r.getString(5));var until=List.of(r.getTimestamp(6).toInstant(),r.getTimestamp(7).toInstant(),r.getTimestamp(10).toInstant()).stream().min(Instant::compareTo).orElseThrow();row.put("minimumUntil",until.toString());row.put("field",r.getString(8));row.put("use",r.getString(9));row.put("timeWindowStillValid",until.isAfter(Instant.now()));rows.add(row);}}}c.rollback();}
 new ObjectMapper().writerWithDefaultPrettyPrinter().writeValue(Path.of(a[0]).toFile(),Map.of("observedAt",Instant.now().toString(),"scope","SOURCE_METADATA_NO_SOURCE_BODY_NO_GOAL","rows",rows,"writes",0,"note","Time validity is not full admission; status, rights, authoritative watermark and task permission remain mandatory"));
 }
}
